
(function(){
 const certificateLogo="data:image/jpeg;base64,";
 const certificateStamp="data:image/jpeg;base64,";
 const courseId="8b097e3a-4a76-4896-a79f-e4097c1b68dc";
 const legacyCourse="Formación Complementaria en Extensiones de Pestañas";
 const verifyBase="https://eddeli1985.github.io/eddeli/?certificado=";
 let statusRequest=0;
 const statuses=new Map();
 let refreshPending;
 const formatDate=value=>new Date(value).toLocaleDateString("es-ES",{day:"numeric",month:"long",year:"numeric",timeZone:"Europe/Madrid"});
 const asAdmin=()=>currentUser&&currentProfile?.role==="admin"&&currentProfile.approval_status==="approved";

 function image(source){
  return new Promise((resolve,reject)=>{
   const asset=new Image();
   asset.onload=()=>resolve(asset);asset.onerror=reject;asset.src=source;
  });
 }
 function makePdf(jpeg,width,height,verificationUrl){
  const encoder=new TextEncoder(),pieces=[];
  let length=0;
  const offsets=[0];
  function push(value){
   const bytes=typeof value==="string"?encoder.encode(value):value;
   length+=bytes.byteLength;pieces.push(bytes);
  }
  function object(id,value){
   offsets[id]=length;
   push(id+" 0 obj\n");push(value);push("\nendobj\n");
  }
  push("%PDF-1.4\n");
  push(new Uint8Array([37,226,227,207,211,10]));
  object(1,"<< /Type /Catalog /Pages 2 0 R >>");
  object(2,"<< /Type /Pages /Kids [3 0 R] /Count 1 >>");
  object(3,"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 841.89 595.28] /Resources << /XObject << /Artwork 4 0 R >> >> /Contents 5 0 R /Annots [6 0 R] >>");
  offsets[4]=length;
  push("4 0 obj\n<< /Type /XObject /Subtype /Image /Width "+width+" /Height "+height+
   " /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length "+jpeg.byteLength+" >>\nstream\n");
  push(jpeg);push("\nendstream\nendobj\n");
  const draw="q\n841.89 0 0 595.28 0 0 cm\n/Artwork Do\nQ\n";
  object(5,"<< /Length "+encoder.encode(draw).length+" >>\nstream\n"+draw+"endstream");
  object(6,"<< /Type /Annot /Subtype /Link /Rect [52 44 389 70] /Border [0 0 0] /A << /S /URI /URI ("+verificationUrl+") >> >>");
  const xref=length;
  push("xref\n0 7\n0000000000 65535 f \n");
  for(let i=1;i<7;i++)push(String(offsets[i]).padStart(10,"0")+" 00000 n \n");
  push("trailer\n<< /Size 7 /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF\n");
  return new Blob(pieces,{type:"application/pdf"});
 }
 async function renderCertificate(record,preview=false){
  const {certificate_code:code,recipient_name:name,course_name:course,issued_at:issuedAt}=record;
  if(!name||!course||(!preview&&(!code||!Number.isFinite(Date.parse(issuedAt)))))throw new Error("Datos del certificado incompletos.");
  const verifiable=/^EDDELI-[0-9A-F]{32}$/.test(code||"");
  const [logo,seal]=await Promise.all([image(certificateLogo),image(certificateStamp)]);
  const canvas=document.createElement("canvas");canvas.width=1754;canvas.height=1240;
  const ctx=canvas.getContext("2d");
  if(!ctx)throw new Error("Vista del certificado no disponible.");
  ctx.fillStyle="#faf6ef";ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.strokeStyle="#b86d65";ctx.lineWidth=3;
  ctx.strokeRect(30,30,1694,1180);ctx.strokeRect(42,42,1670,1156);
  ctx.drawImage(logo,752,65,250,250);
  ctx.drawImage(seal,1257,854,300,300);
  ctx.fillStyle="#4a1230";
  ctx.textAlign="center";ctx.textBaseline="alphabetic";
  function text(value,x,y,size,max,style=""){
   do{
    ctx.font=style+" "+size+"px Georgia, serif";
    size--;
   }while(ctx.measureText(value).width>max&&size>21);
   ctx.fillText(value,x,y,max);
  }
  text("CERTIFICADO DE FINALIZACIÓN",877,391,68,1510,"bold");
  text("Eli Beauty Academy certifica que",877,484,43,1500);
  text(name,877,619,111,1480,"italic");
  text(preview||verifiable?"ha completado y aprobado el curso":"ha aprobado la evaluación teórica del curso",877,710,42,1500);
  text(course,877,799,51,1510,"bold");
  ctx.textAlign="left";
  if(preview){
   ctx.fillStyle="#9c304a";
   text("VISTA PREVIA · SIN VALIDEZ",116,993,40,1040,"bold");
   text("Fecha y código asignados al emitir",116,1056,32,1040);
  }else{
   text("Fecha de emisión: "+formatDate(issuedAt),116,993,32,1040);
   text("Código: "+code,116,1049,27,1040);
   if(verifiable){
    ctx.fillStyle="#145256";
    text("Verificar certificado en EDDELI",116,1131,30,1040,"bold");
   }
  }
  return canvas;
 }
 async function buildCertificate(record){
  if(!/^EDDELI-[0-9A-F]{32}$/.test(record.certificate_code||""))throw new Error("Código no disponible para este PDF.");
  const canvas=await renderCertificate(record);
  const jpeg=await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error("No se pudo preparar el PDF.")),"image/jpeg",.96));
  return makePdf(new Uint8Array(await jpeg.arrayBuffer()),canvas.width,canvas.height,verifyBase+record.certificate_code);
 }
 window.eddeliDownloadCertificate=async function(record){
  try{
   const pdf=await buildCertificate(record);
   const url=URL.createObjectURL(pdf),link=document.createElement("a");
   link.href=url;link.download="Certificado-"+record.certificate_code+".pdf";
   document.body.append(link);link.click();link.remove();
   window.setTimeout(()=>URL.revokeObjectURL(url),30000);
  }catch(error){console.warn("EDDELI: PDF no disponible.",error);alert("No se pudo descargar el PDF. Vuelve a intentarlo.");}
 };
 function printArtwork(artwork,title){
  const popup=window.open("","_blank");
  if(!popup){alert("Permite las ventanas emergentes para imprimir el certificado.");return;}
  const doc=popup.document;
  doc.title=title;
  doc.body.textContent="Preparando la impresión…";
  const css=doc.createElement("style");
  css.textContent="@page{size:A4 landscape;margin:0}html,body{margin:0;padding:0;background:white}img{display:block;width:100%;height:auto}@media print{img{width:297mm;height:210mm;object-fit:contain;break-inside:avoid}}";
  doc.head.append(css);
  Promise.resolve(artwork).then(canvas=>{
   if(popup.closed)return;
   const img=doc.createElement("img");
   img.alt=title;
   img.onload=()=>{if(!popup.closed){popup.focus();popup.print();}};
   doc.body.replaceChildren(img);
   img.src=canvas.toDataURL("image/png");
  }).catch(error=>{
   if(!popup.closed)doc.body.textContent="No se pudo preparar la impresión. Cierra esta ventana y vuelve a intentarlo.";
   console.warn("EDDELI: impresión del certificado no disponible.",error);
  });
 }
 window.eddeliPrintAcademyCertificate=function(record){
  printArtwork(renderCertificate(record),"Certificado de Eli Beauty Academy");
 };
 function describe(status){
  const reasons=[];
  if(!status.enrolled)reasons.push("Matrícula pendiente");
  if(!status.name_ready)reasons.push("Nombre completo o perfil aprobado pendiente");
  if(Number(status.stage_count)!==13)reasons.push("Etapas aprobadas: "+status.stage_count+" de 13");
  if(!status.final_passed)reasons.push("Examen final pendiente de aprobación");
  if(Number(status.practice_count)!==3)reasons.push("Prácticas aprobadas: "+status.practice_count+" de 3");
  return reasons.join("\n")||"Aún hay requisitos pendientes.";
 }
 window.eddeliPreviewAcademyCertificate=async function(studentId,name){
  if(!asAdmin())return;
  const dialog=document.createElement("dialog");
  dialog.className="eddeli-practice-dialog eddeli-certificate-preview";
  dialog.setAttribute("aria-label","Vista previa del certificado");
  const heading=document.createElement("h2");heading.textContent="Vista previa del certificado";
  const close=document.createElement("button");close.type="button";close.className="secondary";close.textContent="Cerrar";
  close.onclick=()=>dialog.close();
  const status=document.createElement("p");status.setAttribute("role","status");status.textContent="Preparando la vista previa…";
  const details=document.createElement("p");
  dialog.append(heading,close,status,details);
  document.body.append(dialog);
  dialog.addEventListener("close",()=>dialog.remove(),{once:true});
  dialog.showModal();
  try{
   const [canvas]=await Promise.all([
    renderCertificate({recipient_name:name==="Sin nombre"?"Nombre completo pendiente":name,course_name:"Formación Complementaria en Extensiones de Pestañas"},true),
    window.eddeliRefreshAcademyCertificates()
   ]);
   if(!dialog.open||!asAdmin())return;
   canvas.className="eddeli-certificate-preview-image";
   canvas.setAttribute("role","img");
   canvas.setAttribute("aria-label","Maqueta del certificado para "+name+" · Vista previa sin validez");
   dialog.insertBefore(canvas,status);
   status.textContent="La vista previa no emite ni envía un certificado.";
   const printPreview=document.createElement("button");
   printPreview.type="button";printPreview.className="secondary";printPreview.textContent="Imprimir vista previa";
   printPreview.onclick=()=>printArtwork(canvas,"Vista previa del certificado de Eli Beauty Academy");
   dialog.insertBefore(printPreview,details);
   const state=statuses.get(studentId);
   if(state?.certificate_code)details.textContent="Ya existe un certificado emitido. Puedes abrirlo desde Gestión de alumnos.";
   else if(state?.ready){
    details.textContent="El alumno ha completado los requisitos.";
    const issue=document.createElement("button");issue.type="button";issue.className="primary";issue.textContent="Autorizar y emitir";
    issue.onclick=async()=>{
     if(!confirm("¿Emitir y entregar el certificado a "+name+" en EDDELI?"))return;
     dialog.close();
     await window.eddeliAcademyCertificateAction(studentId,name);
    };
    dialog.append(issue);
   }else details.textContent=state?"Requisitos pendientes\n"+describe(state):"Estado de los requisitos no disponible.";
  }catch(error){
   if(dialog.open)status.textContent="No se pudo abrir la vista previa. Vuelve a intentarlo.";
  }
 };
 function renderButtons(){
  for(const button of document.querySelectorAll(".eddeli-certificate-button[data-student-id]")){
   if(button.dataset.issuing==="true")continue;
   const state=statuses.get(button.dataset.studentId);
   const emitted=!!state?.certificate_code,ready=state?.ready&&!emitted;
   button.classList.toggle("is-ready",!!ready);
   button.textContent=emitted?"Certificado emitido":ready?"Certificado listo":"Certificado";
   button.title=emitted?"Emitido el "+formatDate(state.issued_at):ready?"Pulsa para emitir y entregar en EDDELI":state?describe(state):"Consultar requisitos del certificado";
   button.setAttribute("aria-label",button.textContent+" · "+button.dataset.studentName);
  }
 }
 window.eddeliRefreshAcademyCertificates=async function(){
  if(!asAdmin()||!document.getElementById("admin-alumnos")?.classList.contains("active"))return;
  if(refreshPending)return refreshPending;
  const request=++statusRequest;
  refreshPending=(async()=>{
   try{
    const result=await supabaseClient.rpc("eddeli_admin_academy_certificate_status");
    if(result.error)throw result.error;
    if(request!==statusRequest||!asAdmin())return;
    statuses.clear();
    for(const state of result.data||[])statuses.set(state.student_id,state);
    renderButtons();
   }catch(error){console.warn("No se pudo consultar el estado de los certificados.",error);}
   finally{refreshPending=null;}
  })();
  return refreshPending;
 };
 function openExisting(record,name){
  if(record.recipient_name&&record.course_name&&/^EDDELI-[0-9A-F]{32}$/.test(record.certificate_code)){
   return window.eddeliDownloadCertificate(record);
  }
  return window.eddeliPrintAcademyCertificate({...record,recipient_name:name,course_name:legacyCourse});
 }
 window.eddeliAcademyCertificateAction=async function(studentId,name,button=null){
  if(!asAdmin())return;
  if(button){
   const cached=statuses.get(studentId);
   if(cached?.certificate_code){await openExisting(cached,name);return;}
   await window.eddeliRefreshAcademyCertificates();
   if(!button.isConnected||button.dataset.issuing==="true")return;
   const state=statuses.get(studentId);
   if(!state){alert("No se pudo confirmar el estado del certificado. Vuelve a intentarlo.");return;}
   if(state.certificate_code){await openExisting(state,name);return;}
   if(!state.ready){await window.eddeliPreviewAcademyCertificate(studentId,name);return;}
   button.dataset.issuing="true";button.disabled=true;button.textContent="Emitiendo…";
  }
  try{
   const response=await supabaseClient.rpc("eddeli_issue_academy_certificate",{p_student_id:studentId});
   if(response.error)throw response.error;
   const record=response.data?.[0];
   if(!record)throw new Error("La emisión no devolvió un certificado.");
   const prior=statuses.get(studentId);
   if(prior)statuses.set(studentId,{...prior,...record});
   alert("Certificado disponible en Mis certificados · "+record.certificate_code);
   if(!button)void loadCertificates(true);
  }catch(error){alert(error.message||"No se pudo emitir el certificado.");}
  finally{
   if(button){button.disabled=false;delete button.dataset.issuing;renderButtons();}
   void window.eddeliRefreshAcademyCertificates();
  }
 };
 function notice(parent,heading,message){
  const item=document.createElement("div");item.className="notice";
  const title=document.createElement("strong");title.textContent=heading;
  const copy=document.createElement("p");copy.textContent=message;item.append(title,copy);parent.prepend(item);return item;
 }
 function clearCertificateNotice(){
  document.getElementById("eddeli-issued-certificate-notice")?.remove();
 }
 async function showCertificateNotice(){
  clearCertificateNotice();
  if(!currentUser||currentProfile?.role!=="student")return;
  const studentId=currentUser.id;
  const response=await supabaseClient.from("certificates").select("certificate_code,issued_at")
   .eq("student_id",studentId).eq("course_id",courseId).not("recipient_name","is",null).maybeSingle();
  if(response.error||!response.data||currentUser?.id!==studentId||!document.getElementById("notificaciones")?.classList.contains("active"))return;
  clearCertificateNotice();
  const host=document.querySelector("#notificaciones .card");
  if(!host)return;
  const row=notice(host,"Tu certificado está disponible","Eli Beauty Academy · "+formatDate(response.data.issued_at));
  row.id="eddeli-issued-certificate-notice";
  const button=document.createElement("button");button.type="button";button.className="primary";button.textContent="Ir a Mis certificados";
  button.onclick=()=>window.go("perfil");row.append(button);
 }
 const originalGo=window.go;
 window.go=function(page){
  const result=originalGo.apply(this,arguments);
  if(page==="notificaciones"&&result)void showCertificateNotice();
  else clearCertificateNotice();
  return result;
 };
 window.setInterval(()=>{void window.eddeliRefreshAcademyCertificates();},30000);
 supabaseClient.auth.onAuthStateChange(event=>{if(event==="SIGNED_OUT"){statuses.clear();statusRequest++;clearCertificateNotice();}});
 const verifyCode=new URLSearchParams(location.search).get("certificado");
 if(verifyCode){
  const host=document.querySelector("main");
  if(host){
   const code=verifyCode.trim().toUpperCase();
   const row=notice(host,"Verificación de certificado","Consultando el código…");
   const message=row.querySelector("p");
   if(!/^EDDELI-[0-9A-F]{32}$/.test(code))message.textContent="El código no tiene un formato válido.";
   else void supabaseClient.rpc("eddeli_verify_academy_certificate",{p_code:code}).then(response=>{
    const certificate=response.data?.[0];
    message.textContent=response.error?"No se pudo verificar el código. Vuelve a intentarlo."
     :certificate?"Código válido · "+certificate.course_name+" · Emitido el "+formatDate(certificate.issued_at)
     :"No se encontró un certificado con ese código.";
   }).catch(()=>{message.textContent="No se pudo verificar el código. Vuelve a intentarlo.";});
  }
 }
})();
